    {run.run.account_selection&&<div className="chat-routing">{run.run.account_selection.account_id||'Account identity unavailable'} · {String(run.run.account_selection.reason||'').replaceAll('_',' ')}</div>}
    {run.run.handoff&&<details className="chat-evidence"><summary>Transferred context{run.run.context_omitted_chars?' · '+run.run.context_omitted_chars+' characters omitted':''}</summary><pre>{stringify(run.run.handoff_context||run.run.prompt||'Context record unavailable')}</pre></details>}
